546: function ConvertTo-PluginSafeFileStem {
547:     param([Parameter(Mandatory)][string]$Value)
548: 
549:     $hashBytes = [System.Security.Cryptography.SHA256]::HashData([System.Text.Encoding]::UTF8.GetBytes($Value))
550:     $hash = ([Convert]::ToHexString($hashBytes)).Substring(0, 12).ToLowerInvariant()
551:     $stem = (($Value -replace '[^A-Za-z0-9._-]+', '-').Trim('-'))
552:     if (-not $stem) { $stem = 'root' }
