71:     /// <inheritdoc />
72:     public async Task<VoiceSessionCreateResponse> CreateSessionAsync(VoiceSessionCreateRequest? request, CancellationToken cancellationToken = default)
73:     {
74:         cancellationToken.ThrowIfCancellationRequested();
75:         EnsureEnabled();
76: 
77:         var opts = _options.CurrentValue;
78:         var now = DateTimeOffset.UtcNow;
79:         var requestedModel = string.IsNullOrWhiteSpace(request?.AgentModel) ? opts.CopilotModel : request.AgentModel.Trim();
80:         var configuredExecutionStrategy = string.IsNullOrWhiteSpace(request?.ExecutionStrategy)
81:             ? opts.DefaultExecutionStrategy
82:             : request.ExecutionStrategy;
83:         var executionStrategy = _strategyResolver.Resolve(configuredExecutionStrategy).Name;
84: 
85:         var requestedAgentName = request?.AgentName;
86:         var requestedWorkspacePath = request?.WorkspacePath;
87:         if (!string.IsNullOrWhiteSpace(requestedAgentName))
88:         {
89:             foreach (var existing in _sessions.Values)
90:             {
91:                 if (!string.Equals(existing.AgentName, requestedAgentName, StringComparison.OrdinalIgnoreCase))
92:                     continue;
93:                 if (!string.Equals(existing.WorkspacePath, requestedWorkspacePath, StringComparison.OrdinalIgnoreCase))
94:                     continue;
95:                 if (!string.Equals(existing.ExecutionStrategy, executionStrategy, StringComparison.OrdinalIgnoreCase))
96:                     continue;
97:                 if (existing.IsTurnActive)
98:                     continue;
99: 
100:                 existing.LastUpdatedUtc = now;
101:                 if (!string.IsNullOrWhiteSpace(request?.AgentPrompt) &&
102:                     existing.InteractiveSession is { IsAlive: true } liveSession)
103:                 {
104:                     _ = await liveSession.SendAsync(request.AgentPrompt, cancellationToken).ConfigureAwait(false);
105:                 }
106: 
107:                 _logger.LogInformation("Reusing voice session {SessionId} for pooled agent {AgentName}", existing.SessionId, requestedAgentName);
108:                 return new VoiceSessionCreateResponse
109:                 {
110:                     ExecutionStrategy = existing.ExecutionStrategy,
111:                     SessionId = existing.SessionId,
112:                     Status = existing.Status,
113:                     Language = existing.Language,
114:                     ModelRequested = requestedModel,
115:                     ModelResolved = requestedModel,
116:                 };
117:             }
118:         }
119: 
120:         // Enforce one-session-per-device: close any existing session for this device
121:         if (!string.IsNullOrWhiteSpace(request?.DeviceId))
122:         {
123:             foreach (var kvp in _sessions)
124:             {
125:                 if (string.Equals(kvp.Value.DeviceId, request.DeviceId, StringComparison.OrdinalIgnoreCase))
126:                 {
127:                     _logger.LogInformation("Closing existing session {OldSessionId} for device {DeviceId}", kvp.Key, request.DeviceId);
128:                     await DeleteSessionAsync(kvp.Key, cancellationToken).ConfigureAwait(false);
129:                 }
130:             }
131:         }
132: 
133:         var sessionId = $"voice-{now:yyyyMMddHHmmss}-{Guid.NewGuid():N}".ToLowerInvariant();
134:         var language = NormalizeLanguage(request?.Language);
135:         var combinedSeed = request?.AgentSeed;
136:         if (!string.IsNullOrWhiteSpace(request?.AgentPrompt))
137:             combinedSeed = string.IsNullOrWhiteSpace(combinedSeed)
138:                 ? request.AgentPrompt
139:                 : $"{combinedSeed}{Environment.NewLine}{Environment.NewLine}{request.AgentPrompt}";
140: 
141:         var state = new VoiceSessionState(
142:             sessionId,
143:             language,
144:             request?.DeviceId,
145:             request?.ClientName,
146:             request?.WorkspacePath,
147:             request?.AgentName,
148:             request?.AgentPath,
149:             requestedModel,
150:             combinedSeed,
151:             request?.AgentParameters,
152:             executionStrategy,
153:             request?.OneShotSession ?? false,
154:             now);
155:         _sessions[sessionId] = state;
156: 
157:         _logger.LogInformation("Created voice session {SessionId} for device {DeviceId}", sessionId, request?.DeviceId ?? "(none)");
158: 
159:         return new VoiceSessionCreateResponse
160:         {
161:             ExecutionStrategy = executionStrategy,
162:             SessionId = sessionId,
163:             Status = "idle",
164:             Language = language,
165:             ModelRequested = requestedModel,
166:             ModelResolved = requestedModel
167:         };
168:     }
