4: namespace QBrainAi.Support.Mcp.Tests.Services;
5: 
6: /// <summary>
7: /// TR-MCP-DB-006 / TEST-MCP-DB-006 (BUG-TRIAGE-079): the KeyedAsyncLock serializes concurrent work on
8: /// the same key (so a burst of session-log turn deletes on one session cannot poison the SQL Server
9: /// pool) while letting different keys run concurrently. The pair discriminates a correct keyed lock
10: /// from a no-op (fails SameKey) and from a global lock (fails DifferentKeys). Deterministic: uses
11: /// Task.WhenAny timing rather than blocking waits.
12: /// </summary>
13: public sealed class KeyedAsyncLockTests
14: {
15:     /// <summary>A second acquire of the same key blocks until the first is released.</summary>
16:     [Fact]
17:     public async Task AcquireAsync_SameKey_BlocksUntilReleased()
18:     {
19:         var ct = TestContext.Current.CancellationToken;
20:         var sut = new KeyedAsyncLock();
21: 
22:         var first = await sut.AcquireAsync("session-A", ct).ConfigureAwait(true);
23:         var second = sut.AcquireAsync("session-A", ct);
24: 
25:         var early = await Task.WhenAny(second, Task.Delay(250, ct)).ConfigureAwait(true);
26:         Assert.NotSame(second, early);
27: 
28:         await first.DisposeAsync().ConfigureAwait(true);
29: 
30:         var afterRelease = await Task.WhenAny(second, Task.Delay(2000, ct)).ConfigureAwait(true);
31:         Assert.Same(second, afterRelease);
32:         await (await second.ConfigureAwait(true)).DisposeAsync().ConfigureAwait(true);
33:     }
34: 
35:     /// <summary>A second acquire of a different key completes while the first key is still held.</summary>
36:     [Fact]
37:     public async Task AcquireAsync_DifferentKeys_DoNotBlockEachOther()
38:     {
39:         var ct = TestContext.Current.CancellationToken;
40:         var sut = new KeyedAsyncLock();
41: 
42:         await using (await sut.AcquireAsync("session-A", ct).ConfigureAwait(true))
43:         {
44:             var acquireB = sut.AcquireAsync("session-B", ct);
45:             var completed = await Task.WhenAny(acquireB, Task.Delay(2000, ct)).ConfigureAwait(true);
46:             Assert.Same(acquireB, completed);
47:             await (await acquireB.ConfigureAwait(true)).DisposeAsync().ConfigureAwait(true);
48:         }
49:     }
50: }

