3: /// <summary>TR-MCP-NUKE-020 AC-1 and AC-5: one TestGroups run: the lane-shaped run record and the classes it names.</summary>
4: /// <param name="Run">The project, path, filter, log line and TRX name, as the lane composes them.</param>
5: /// <param name="Classes">The classes this run's groups named, in first-seen order.</param>
6: /// <remarks>
7: /// <list type="table">
8: /// <listheader><term>Date</term><description>Requirements; AC; change and reason</description></listheader>
9: /// <item><term>2026-11-02</term><description>FR-MCP-BUILD-001; TR-MCP-NUKE-020 AC-1, AC-5: added so the target can check every named class of a project's merged groups against that project's TRX.</description></item>
10: /// </list>
11: /// </remarks>
12: internal sealed record TestGroupRun(IntegrationLaneRun Run, IReadOnlyList<string> Classes);
13: 
14: /// <summary>
15: /// TR-MCP-NUKE-020 AC-1, AC-2, AC-4 and AC-5: pure composition and result checks of the TestGroups target. Each
16: /// <c>--test-groups</c> value is <c>&lt;test project&gt;:&lt;Class&gt;[,&lt;Class&gt;...]</c>; groups that name one project merge
17: /// into one run in first-seen order, so each selected project writes one TRX. The filter is the lane's host platform
18: /// clause (<see cref="IntegrationLaneFilter.PlatformClause"/>) and class clause
19: /// (<see cref="IntegrationLaneClassFilter.ClassClause"/>), with no category clause; the run record, log line and TRX name
20: /// follow the lane's <see cref="IntegrationLaneRun"/>. Every refusal happens before any test runs.
21: /// </summary>
22: /// <remarks>
23: /// <list type="table">
24: /// <listheader><term>Date</term><description>Requirements; AC; change and reason</description></listheader>
25: /// <item><term>2026-11-02</term><description>FR-MCP-BUILD-001; TR-MCP-NUKE-020 AC-1, AC-2, AC-3: added the TestGroups composition and run-id policy so targeted runs go through Nuke (operator 2026-11-02) and reuse the lane composition.</description></item>
26: /// <item><term>2026-11-02</term><description>FR-MCP-BUILD-001; TR-MCP-NUKE-020 AC-4, AC-5: added the host platform clause and the per-class result check after a Windows-only class was run on Linux.</description></item>
27: /// </list>
28: /// </remarks>
29: internal static class TestGroupExecution
30: {
31:     /// <summary>Composes the runs for the given groups against the solution's projects on one host.</summary>
32:     /// <param name="groups">The <c>--test-groups</c> values, in order.</param>
33:     /// <param name="projects">The solution's project names and paths.</param>
34:     /// <param name="host">The host the runs execute on.</param>
35:     /// <returns>One run per selected project, in the order the groups first name them.</returns>
36:     /// <exception cref="InvalidOperationException">No group, a malformed group, an unknown or blank project, or a class
37:     /// name that is empty or not a plain class name.</exception>
38:     /// <remarks>
39:     /// <list type="table">
40:     /// <listheader><term>Date</term><description>Requirements; AC; change and reason</description></listheader>
41:     /// <item><term>2026-11-02</term><description>FR-MCP-BUILD-001; TR-MCP-NUKE-020 AC-1, AC-2: added; one run per project with the lane's class clause and run record.</description></item>
42:     /// <item><term>2026-11-02</term><description>FR-MCP-BUILD-001; TR-MCP-NUKE-020 AC-4: added the host parameter and the platform clause so other-platform cases never run.</description></item>
43:     /// </list>
44:     /// </remarks>
45:     internal static IReadOnlyList<TestGroupRun> Compose(IReadOnlyList<string> groups, IReadOnlyList<(string Name, string Path)> projects, IntegrationLaneHost host)
46:     {
47:         ArgumentNullException.ThrowIfNull(groups);
48:         ArgumentNullException.ThrowIfNull(projects);
49:         if (groups.Count == 0)
50:             throw new InvalidOperationException("TestGroups needs at least one --test-groups value '<test project>:<Class>[,<Class>...]'.");
51: 
52:         var platform = IntegrationLaneFilter.PlatformClause(host);
53:         var order = new List<string>();
54:         var classes = new Dictionary<string, List<string>>(StringComparer.Ordinal);
55:         foreach (var raw in groups)
56:         {
57:             var group = raw ?? string.Empty;
58:             var separator = group.IndexOf(':', StringComparison.Ordinal);
59:             if (separator < 0)
60:                 throw new InvalidOperationException($"Test group '{group}' must be '<test project>:<Class>[,<Class>...]'.");
61: 
62:             var project = group[..separator].Trim();
63:             if (project.Length == 0)
64:                 throw new InvalidOperationException($"Test group '{group}' names no test project.");
65:             if (!projects.Any(entry => string.Equals(entry.Name, project, StringComparison.Ordinal)))
66:                 throw new InvalidOperationException($"Test group '{group}' names test project '{project}', which the solution does not contain.");
67: 
68:             var names = group[(separator + 1)..].Split(',').Select(name => name.Trim()).ToArray();
69:             if (names.Any(name => name.Length == 0))
70:                 throw new InvalidOperationException($"Test group '{group}' has an empty class name.");
71:             foreach (var name in names)
72:             {
73:                 try
74:                 {
75:                     IntegrationLaneClassFilter.ClassClause([name]);
76:                 }
77:                 catch (ArgumentException)
78:                 {
79:                     throw new InvalidOperationException($"Test group '{group}' names class '{name}', which is not a plain class name.");
80:                 }
81:             }
82: 
83:             if (!classes.TryGetValue(project, out var selected))
84:             {
85:                 selected = [];
86:                 classes[project] = selected;
87:                 order.Add(project);
88:             }
89: 
90:             foreach (var name in names.Where(name => !selected.Contains(name, StringComparer.Ordinal)))
91:                 selected.Add(name);
92:         }
93: 
94:         return order.Select(name =>
95:         {
96:             var path = projects.First(entry => string.Equals(entry.Name, name, StringComparison.Ordinal)).Path;
97:             var filter = platform + "&" + IntegrationLaneClassFilter.ClassClause(classes[name]);
98:             return new TestGroupRun(
99:                 new IntegrationLaneRun(name, path, filter, $"Test group filter for {name}: {filter}", name + ".trx"),
100:                 classes[name].ToArray());
101:         }).ToArray();
102:     }
103: 
104:     /// <summary>TR-MCP-NUKE-020 AC-1: TestGroups always writes TRX receipts, so it requires a safe --test-run-id.</summary>
105:     /// <param name="testRunId">The raw <c>--test-run-id</c> value.</param>
106:     /// <returns>The run id.</returns>
107:     /// <exception cref="InvalidOperationException">The id is blank or not a single path segment.</exception>
108:     /// <remarks>
109:     /// <list type="table">
110:     /// <listheader><term>Date</term><description>Requirements; AC; change and reason</description></listheader>
111:     /// <item><term>2026-11-02</term><description>FR-MCP-BUILD-001; TR-MCP-NUKE-020 AC-1: added so a targeted run always leaves TRX receipts.</description></item>
112:     /// </list>
113:     /// </remarks>
114:     internal static string RequireRunId(string testRunId) =>
115:         SessionLifeUnitGateReports.NormalizeRunId(testRunId)
116:             ?? throw new InvalidOperationException("TestGroups requires --test-run-id, so that every selected project writes its TRX receipt.");
117: 
118:     /// <summary>
119:     /// TR-MCP-NUKE-020 AC-5: every named class ran at least one case. A class counts only through an executed result (an
120:     /// outcome other than NotExecuted) whose test, joined to its definition by test id, belongs to the class: the
121:     /// definition's TestMethod class name is the class, as the whole name or its last segment ('.' or '+' separated). A
122:     /// definition with no executed result, a display name and a namespace segment never count; a custom display name
123:     /// counts through its test's class.
124:     /// </summary>
125:     /// <param name="project">The project whose TRX is checked.</param>
126:     /// <param name="classes">The classes the project's groups named.</param>
127:     /// <param name="xml">The complete TRX content.</param>
128:     /// <returns>Null when every class ran a case; otherwise the failure, naming each class that ran none.</returns>
129:     /// <remarks>
130:     /// <list type="table">
131:     /// <listheader><term>Date</term><description>Requirements; AC; change and reason</description></listheader>
132:     /// <item><term>2026-11-02</term><description>FR-MCP-BUILD-001; TR-MCP-NUKE-020 AC-5: added so a misspelled class in a multi-class group fails instead of passing silently.</description></item>
133:     /// <item><term>2026-11-02</term><description>FR-MCP-BUILD-001; TR-MCP-NUKE-020 AC-5 (appended: a class counts only through an executed result joined to its definition by test id): joins each executed result to its definition and compares the definition's class name, instead of matching text in display names and every definition, because hostile validation finding R9-F1 showed a definition without a result, a display name or a namespace segment satisfied the check (operator 2026-11-02: "Strengthen 5 ACs, fix all 8 (Recommended)").</description></item>
134:     /// </list>
135:     /// </remarks>
136:     internal static string? CheckClasses(string project, IReadOnlyList<string> classes, string xml)
137:     {
138:         ArgumentNullException.ThrowIfNull(classes);
139:         string[] executedClasses;
140:         try
141:         {
142:             var document = XDocument.Parse(xml);
143:             var classById = document.Descendants()
144:                 .Where(element => element.Name.LocalName == "UnitTest")
145:                 .Select(test => (Id: (string?)test.Attribute("id"), ClassName: (string?)test.Elements().FirstOrDefault(child => child.Name.LocalName == "TestMethod")?.Attribute("className")))
146:                 .Where(test => !string.IsNullOrEmpty(test.Id) && !string.IsNullOrEmpty(test.ClassName))
147:                 .GroupBy(test => test.Id!, StringComparer.Ordinal)
148:                 .ToDictionary(group => group.Key, group => group.First().ClassName!, StringComparer.Ordinal);
149:             executedClasses = document.Descendants()
150:                 .Where(element => element.Name.LocalName == "UnitTestResult")
151:                 .Where(result => !string.Equals((string?)result.Attribute("outcome"), "NotExecuted", StringComparison.Ordinal))
152:                 .Select(result => (string?)result.Attribute("testId"))
153:                 .Where(id => id is not null && classById.ContainsKey(id))
154:                 .Select(id => classById[id!])
155:                 .ToArray();
156:         }
157:         catch (System.Xml.XmlException error)
158:         {
159:             return $"Test group project '{project}' wrote unreadable TRX evidence, so classes {string.Join(", ", classes)} are unproven: {error.Message}";
160:         }
161: 
162:         var missing = classes.Where(name => !executedClasses.Any(className => IsClass(className, name))).ToArray();
163:         return missing.Length == 0
164:             ? null
165:             : $"Test group project '{project}' ran no case of class {string.Join(", ", missing)}.";
166:     }
167: 
168:     /// <summary>
169:     /// TR-MCP-NUKE-020 AC-5: whether a definition's class name is the named class, as the whole name or its last segment
170:     /// ('.' or '+' separated, '+' marking a nested class).
171:     /// </summary>
172:     /// <param name="className">The definition's TestMethod class name.</param>
173:     /// <param name="name">The class a group names.</param>
174:     /// <returns>True when the definition belongs to the named class.</returns>
175:     /// <remarks>2026-11-02, FR-MCP-BUILD-001; TR-MCP-NUKE-020 AC-5: added for hostile validation finding R9-F1.</remarks>
176:     private static bool IsClass(string className, string name) =>
177:         string.Equals(className, name, StringComparison.Ordinal)
178:         || className.EndsWith("." + name, StringComparison.Ordinal)
179:         || className.EndsWith("+" + name, StringComparison.Ordinal);
180: }

