340:     static Version GetNewestLocalDbEngineVersion(string sqlLocalDbExe)
341:     {
342:         var output = RunToolCapture(sqlLocalDbExe, "versions");
343:         return System.Text.RegularExpressions.Regex.Matches(output, @"\((\d+)\.(\d+)")
344:             .Select(m => new Version(
345:                 int.Parse(m.Groups[1].Value, System.Globalization.CultureInfo.InvariantCulture),
346:                 int.Parse(m.Groups[2].Value, System.Globalization.CultureInfo.InvariantCulture)))
347:             .DefaultIfEmpty(new Version(0, 0))
348:             .Max() ?? new Version(0, 0);
349:     }
