351:     static string? FindSqlLocalDbExe()
352:     {
353:         var root = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles), "Microsoft SQL Server");
354:         if (!Directory.Exists(root))
355:             return null;
356:         var enumeration = new EnumerationOptions
357:         {
358:             RecurseSubdirectories = true,
359:             IgnoreInaccessible = true,
360:         };
361:         return Directory
362:             .EnumerateFiles(root, "SqlLocalDB.exe", enumeration)
363:             .OrderByDescending(p => p)
364:             .FirstOrDefault();
365:     }
