405:     static void RunTool(string fileName, string arguments)
406:     {
407:         var process = Process.Start(new ProcessStartInfo
408:         {
409:             FileName = fileName,
410:             Arguments = arguments,
411:             UseShellExecute = false,
412:         }) ?? throw new InvalidOperationException($"Failed to start {fileName}.");
413:         process.WaitForExit();
414:         if (process.ExitCode != 0)
415:             throw new InvalidOperationException($"{Path.GetFileName(fileName)} {arguments.Split(' ')[0]} failed with exit code {process.ExitCode}.");
416:     }
