418:     static string RunToolCapture(string fileName, string arguments)
419:     {
420:         var process = Process.Start(new ProcessStartInfo
421:         {
422:             FileName = fileName,
423:             Arguments = arguments,
424:             UseShellExecute = false,
425:             RedirectStandardOutput = true,
426:             RedirectStandardError = true,
427:             CreateNoWindow = true,
428:         }) ?? throw new InvalidOperationException($"Failed to start {fileName}.");
429:         var stdout = process.StandardOutput.ReadToEnd();
430:         _ = process.StandardError.ReadToEnd();
431:         process.WaitForExit();
432:         if (process.ExitCode != 0)
433:             throw new InvalidOperationException($"{Path.GetFileName(fileName)} {arguments} failed with exit code {process.ExitCode}.");
434:         return stdout;
435:     }
