20: {
21:     private static readonly EnumerationOptions s_singleLevel = new()
22:     {
23:         RecurseSubdirectories = false,
24:         IgnoreInaccessible = false,
25:         AttributesToSkip = 0,
26:         ReturnSpecialDirectories = false,
27:     };
28: 
29:     private readonly Func<string, IReadOnlyList<DirectoryListingEntry>> _list;
30:     private readonly WorkspacePathPlatform? _platform;
31: 
32:     /// <summary>Creates a walker that lists each directory through <paramref name="list"/>.</summary>
33:     /// <param name="list">Lists one directory, or throws when it cannot be listed.</param>
34:     /// <param name="platform">Explicit path policy; when absent the boundary's syntax selects it.</param>
35:     internal DirectoryTreeWalker(Func<string, IReadOnlyList<DirectoryListingEntry>> list, WorkspacePathPlatform? platform = null)
36:     {
