43:     internal static DirectoryTreeWalker FileSystem => new(ListFileSystem,
44:         OperatingSystem.IsWindows() ? WorkspacePathPlatform.Windows : WorkspacePathPlatform.CaseSensitive);
45: 
46:     /// <summary>Every directory below <paramref name="root"/> that the walk reaches.</summary>
47:     /// <param name="root">Directory to walk; it is listed but not yielded.</param>
48:     /// <returns>The reached directories, breadth first.</returns>
