78:         var target = Canonical(root);
79:         var current = Canonical(boundary);
80:         while (!string.Equals(current, target, comparison))
81:         {
82:             IReadOnlyList<DirectoryListingEntry> entries;
83:             try
84:             {
85:                 entries = _list(current);
86:             }
87:             catch (IOException)
88:             {
89:                 return false;
90:             }
91:             catch (UnauthorizedAccessException)
92:             {
93:                 return false;
94:             }
95: 
96:             var found = entries
97:                 .Select(entry => entry with { Path = Canonical(entry.Path) })
98:                 .Where(entry => LeadsTo(entry.Path, target, comparison))
99:                 .Select(entry => (DirectoryListingEntry?)entry)
100:                 .FirstOrDefault();
101:             if (found is not { } next || !next.IsDirectory || next.IsLink || next.Path.Length <= current.Length)
102:                 return false;
