120:         new DirectoryInfo(directory)
121:             .EnumerateFileSystemInfos("*", s_singleLevel)
122:             .Select(info => new DirectoryListingEntry(
123:                 info.FullName,
124:                 info is DirectoryInfo,
125:                 (info.Attributes & FileAttributes.ReparsePoint) != 0))
126:             .ToList();
