128:     private IEnumerable<string> Walk(string root, bool yieldDirectories)
129:     {
130:         var pending = new Queue<string>();
131:         pending.Enqueue(root);
132:         while (pending.Count > 0)
133:         {
134:             foreach (var entry in TryList(pending.Dequeue()))
135:             {
136:                 if (entry.IsDirectory)
137:                 {
138:                     if (entry.IsLink)
139:                         continue;
140:                     pending.Enqueue(entry.Path);
141:                     if (yieldDirectories)
142:                         yield return entry.Path;
143:                 }
144:                 else if (!yieldDirectories)
145:                 {
146:                     yield return entry.Path;
147:                 }
148:             }
149:         }
150:     }
151: 
152:     private IReadOnlyList<DirectoryListingEntry> TryList(string directory)
153:     {
154:         try
155:         {
156:             return _list(directory);
157:         }
158:         catch (IOException)
159:         {
160:             return [];
161:         }
162:         catch (UnauthorizedAccessException)
163:         {
164:             return [];
165:         }
166:     }
