311:     private async Task<MarkerSettings> WaitForMarkerAsync()
312:     {
313:         using var timeout = new CancellationTokenSource(MarkerTimeout);
314:         using var watcher = new FileSystemWatcher(WorkspacePath, MarkerFileService.MarkerFileName)
315:         {
316:             NotifyFilter = NotifyFilters.CreationTime
317:                 | NotifyFilters.FileName
318:                 | NotifyFilters.LastWrite
319:                 | NotifyFilters.Size,
320:         };
321:         var signal = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
322:         FileSystemEventHandler onChanged = (_, _) => signal.TrySetResult();
323:         RenamedEventHandler onRenamed = (_, _) => signal.TrySetResult();
324:         watcher.Created += onChanged;
325:         watcher.Changed += onChanged;
326:         watcher.Renamed += onRenamed;
327:         watcher.EnableRaisingEvents = true;
328: 
329:         while (!timeout.IsCancellationRequested)
330:         {
331:             if (TryReadMarker(out var marker))
332:             {
333:                 return marker!;
334:             }
335: 
336:             if (_process is { HasExited: true })
337:             {
338:                 // Drain the redirected output so the message and the restart check see all of it.
339:                 await _process.WaitForExitAsync().ConfigureAwait(false);
340:                 throw new InvalidOperationException(
341:                     $"QBrain.AI exited before generating '{MarkerPath}' with code {_process.ExitCode}.{Environment.NewLine}{Diagnostics}");
342:             }
343: 
344:             var delay = Task.Delay(TimeSpan.FromMilliseconds(250), timeout.Token);
345:             var completed = await Task.WhenAny(signal.Task, delay).ConfigureAwait(false);
346:             if (completed == signal.Task)
347:             {
348:                 signal = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
349:             }
350:         }
351: 
352:         throw new TimeoutException(
353:             $"Timed out after {MarkerTimeout} waiting for generated marker '{MarkerPath}'.{Environment.NewLine}{Diagnostics}");
354:     }
