175:     /// <summary>TR-MCP-SERVICEUPDATE-001 startup-health-wait: seconds between health probes after the start.</summary>
176:     internal static readonly TimeSpan StartupHealthInterval = TimeSpan.FromSeconds(5);
177: 
178:     /// <summary>TR-MCP-SERVICEUPDATE-001 startup-health-wait: probes allowed after the start, 10 minutes at the interval.</summary>
179:     internal const int StartupHealthProbes = 120;
180: 
181:     /// <summary>
182:     /// TR-MCP-SERVICEUPDATE-001 startup-health-wait: waits for HTTP health after the start while the unit stays active,
183:     /// for up to <see cref="StartupHealthProbes"/> probes <see cref="StartupHealthInterval"/> apart, and throws when the
184:     /// unit leaves the active state or the probes are spent, so a server that is still starting is never stopped as
185:     /// unhealthy.
186:     /// </summary>
187:     /// <param name="service">The unit.</param>
188:     /// <param name="probe">One health probe; true when the server answers healthy.</param>
189:     /// <remarks>
190:     /// <list type="table">
191:     /// <item><term>2026-11-04</term><description>TR-MCP-SERVICEUPDATE-001 criteria startup-health-wait and lifecycle
192:     /// (slice Z3): new. The redeploy of 2026-11-04 stopped a server that was starting normally, because the update probed
193:     /// health 10 times 2 s apart while the server registers every workspace before it listens (93 s at 14:27).</description></item>
194:     /// </list>
195:     /// </remarks>
196:     internal void WaitForStartupHealth(string service, Func<bool> probe)
197:     {
198:         var result = EvaluateStartupHealth(() => Value(GetUnit(service), "ActiveState"), probe, Thread.Sleep, StartupHealthProbes, StartupHealthInterval);
199:         if (result.Outcome == StartupHealthOutcome.UnitStopped)
200:             throw new InvalidOperationException("Updated service left the active state before it answered health.");
201:         if (result.Outcome == StartupHealthOutcome.TimedOut)
202:             throw new InvalidOperationException("Updated service did not answer health within the startup wait.");
203:         Log.Information("  Startup health answered after {Probes} probe(s).", result.Probes);
204:     }
