206:     /// <summary>
207:     /// TR-MCP-SERVICEUPDATE-001 startup-health-wait: the wait itself, over an injected unit state, probe and sleep. Before
208:     /// each probe it reads the unit; a unit that is not active ends the wait at once. It sleeps only between probes and
209:     /// stops after <paramref name="maxProbes"/>.
210:     /// </summary>
211:     /// <param name="activeState">Reads the unit's ActiveState.</param>
212:     /// <param name="probe">One health probe.</param>
213:     /// <param name="sleep">Waits between probes.</param>
214:     /// <param name="maxProbes">The probes allowed.</param>
215:     /// <param name="interval">The wait between probes.</param>
216:     /// <returns>The outcome and the probes made.</returns>
217:     /// <remarks>
218:     /// <list type="table">
219:     /// <item><term>2026-11-04</term><description>TR-MCP-SERVICEUPDATE-001 criteria startup-health-wait and lifecycle
220:     /// (slice Z3): new. Its contract rows are ServiceStartupHealthContractTests.Rows, proven against a reference wait and
221:     /// five wrong waits in mock gate ug-r12z3-mockgate-2 before this change.</description></item>
222:     /// </list>
223:     /// </remarks>
224:     internal static StartupHealthResult EvaluateStartupHealth(Func<string> activeState, Func<bool> probe, Action<TimeSpan> sleep, int maxProbes, TimeSpan interval)
225:     {
226:         var probes = 0;
227:         while (probes < maxProbes)
228:         {
229:             if (!string.Equals(activeState(), "active", StringComparison.Ordinal))
230:                 return new(StartupHealthOutcome.UnitStopped, probes);
231:             probes++;
232:             if (probe())
233:                 return new(StartupHealthOutcome.Healthy, probes);
234:             if (probes < maxProbes)
235:                 sleep(interval);
236:         }
237:         return new(StartupHealthOutcome.TimedOut, probes);
238:     }
