240:     /// <summary>
241:     /// TR-MCP-SERVICEUPDATE-001 startup-health-wait: one quiet probe of the loopback health endpoint (3 s timeout); a
242:     /// refused or timed-out request is "not yet", not an error.
243:     /// </summary>
244:     /// <param name="port">The service HTTP port.</param>
245:     /// <returns>True when /health answers with a success status.</returns>
246:     /// <remarks>
247:     /// <list type="table">
248:     /// <item><term>2026-11-04</term><description>TR-MCP-SERVICEUPDATE-001 criterion startup-health-wait (slice Z3): new, so
249:     /// the startup wait does not log an error for every probe the starting server refuses.</description></item>
250:     /// </list>
251:     /// </remarks>
252:     internal static bool ProbeHealth(int port)
253:     {
254:         using var client = new HttpClient { Timeout = TimeSpan.FromSeconds(3) };
255:         try { return client.GetAsync($"http://localhost:{port}/health").GetAwaiter().GetResult().IsSuccessStatusCode; }
256:         catch (HttpRequestException) { return false; }
257:         catch (TaskCanceledException) { return false; }
258:     }
