260:     /// <summary>TR-MCP-SERVICEUPDATE-001: systemd simple units report start before exec; bound retries until the active main process resolves to the deployed apphost.</summary>
261:     private int WaitForServiceProcess(string service, string executable)
262:     {
263:         const int attempts = 100;
264:         for (var attempt = 0; attempt < attempts; attempt++)
265:         {
266:             var state = GetUnit(service);
267:             var activeState = Value(state, "ActiveState");
268:             if (activeState is "failed" or "inactive")
269:                 throw new InvalidOperationException("Updated service stopped before its application process became ready.");
270:             if (activeState == "active" && int.TryParse(Value(state, "MainPID"), out var pid) && pid > 0)
271:             {
272:                 var process = run("readlink", ["-f", $"/proc/{pid}/exe"]);
273:                 if (process.ExitCode == 0 && process.StandardOutput.Trim() == executable)
274:                     return pid;
275:             }
276:             if (attempt < attempts - 1) Thread.Sleep(100);
277:         }
278:         throw new InvalidOperationException("Updated service did not become active with the expected executable within the startup retry limit.");
279:     }
280:     /// <summary>Gets only required systemd properties; sensitive values remain local.</summary>
281:     /// <remarks>
282:     /// <list type="table">
283:     /// <item><term>2026-11-04</term><description>TR-MCP-SERVICEUPDATE-001 criteria repeated-properties, preserve and lifecycle
284:     /// (slice Z3): the output is read through <see cref="ParseUnitProperties"/>, because systemd 262 prints one
285:     /// EnvironmentFiles line per environment file and keying the lines with ToDictionary threw on the second line, before
286:     /// any service change (redeploy of 2026-11-04).</description></item>
287:     /// </list>
288:     /// </remarks>
289:     private Dictionary<string, string> GetUnit(string name) => ParseUnitProperties(Command("systemctl", "show", name, "--no-pager", "--property=" + UnitProperties));
290: 
291:     /// <summary>
292:     /// TR-MCP-SERVICEUPDATE-001 repeated-properties: reads systemctl show output into properties by name. Repeated lines
293:     /// of one property are one value, their non-empty values in order separated by one space, which ParseEnvironmentFiles
294:     /// and ParseWords read as a list; a repeated ExecStart still fails ValidateUnit's single-command check. Lines without a
295:     /// property are ignored and carriage returns are removed.
296:     /// </summary>
297:     /// <param name="output">The systemctl show output.</param>
298:     /// <returns>The properties by name.</returns>
299:     /// <remarks>
300:     /// <list type="table">
301:     /// <item><term>2026-11-04</term><description>TR-MCP-SERVICEUPDATE-001 criteria repeated-properties, preserve and lifecycle
302:     /// (slice Z3): new. Its contract rows are ServiceUnitPropertiesContractTests.Rows, proven against a reference reader
303:     /// and six wrong readers in mock gate ug-r12z3-mockgate-1 before this change.</description></item>
304:     /// </list>
305:     /// </remarks>
306:     internal static Dictionary<string, string> ParseUnitProperties(string output)
307:     {
308:         var properties = new Dictionary<string, string>(StringComparer.Ordinal);
309:         foreach (var line in output.Split('\n'))
310:         {
311:             var separator = line.IndexOf('=', StringComparison.Ordinal);
312:             if (separator < 0) continue;
313:             var key = line[..separator];
314:             var value = line[(separator + 1)..].TrimEnd('\r');
315:             if (!properties.TryGetValue(key, out var existing)) properties[key] = value;
316:             else if (value.Length > 0) properties[key] = existing.Length == 0 ? value : existing + " " + value;
317:         }
318:         return properties;
319:     }
