324:     /// <summary>Checks installed unit identity before any service mutation.</summary>
325:     private static void ValidateUnit(IReadOnlyDictionary<string, string> unit, string install)
326:     {
327:         if (Value(unit, "LoadState") != "loaded" || Value(unit, "Type") is not ("simple" or "exec" or "notify"))
328:             throw new InvalidOperationException("An existing loaded simple, exec or notify service is required.");
329:         if (new[] { "RootDirectory", "RootImage", "BindPaths", "BindReadOnlyPaths", "TemporaryFileSystem", "MountImages", "ExtensionImages", "ExtensionDirectories" }
330:             .Any(property => !string.IsNullOrWhiteSpace(Value(unit, property))) || Value(unit, "PrivateTmp") is not ("" or "no" or "false"))
331:             throw new InvalidOperationException("Services with filesystem namespace remapping are unsupported.");
332:         if (Decode(Value(unit, "WorkingDirectory")) != install)
333:             throw new InvalidOperationException("Service WorkingDirectory must match the selected install path.");
334:         var start = Value(unit, "ExecStart");
335:         var executable = Regex.Match(start, @"^\{ path=(.*?) ; argv\[\]=(.*?) ; ignore_errors=", RegexOptions.CultureInvariant);
336:         if (!executable.Success || start.Count(c => c == '{') != 1 || !IsAcceptedAppHost(install, Decode(executable.Groups[1].Value)))
337:             throw new InvalidOperationException("Service ExecStart must directly run the selected application host.");
338:         ValidateArguments(ParseWords(executable.Groups[2].Value));
339:     }
