341:     /// <summary>Accepts the current host and the 1.x McpServer host under the selected install directory.</summary>
342:     private static bool IsAcceptedAppHost(string install, string executable)
343:         => string.Equals(executable, Path.Combine(install, AppHost), StringComparison.Ordinal)
344:            || string.Equals(executable, Path.Combine(install, LegacyAppHost), StringComparison.Ordinal);
