346:     /// <summary>
347:     /// TR-MCP-QBRAIN-006: After files are replaced, a preserved unit or drop-in that still names McpServer.Support.Mcp
348:     /// is retargeted at QBrainAi.Support.Mcp before daemon-reload. The effective ExecStart may live in a drop-in.
349:     /// </summary>
350:     /// <param name="unit">The unit properties read before the update.</param>
351:     /// <param name="install">The install folder.</param>
352:     /// <returns>True when a unit file or drop-in was retargeted; false when the unit does not run the legacy apphost.</returns>
353:     /// <exception cref="InvalidOperationException">The unit runs the legacy apphost but no unit file or drop-in names it.</exception>
354:     /// <remarks>
355:     /// <list type="table">
356:     /// <item><term>2026-11-04</term><description>TR-MCP-SERVICEUPDATE-001 criterion failed-update-startable (slice Z3,
357:     /// finding d3 of the fifth holistic read): now returns whether it retargeted a file, so the failure path reloads
358:     /// systemd only after a change; the retargeting itself is unchanged.</description></item>
359:     /// </list>
360:     /// </remarks>
361:     private bool RetargetLegacyExecStart(IReadOnlyDictionary<string, string> unit, string install)
362:     {
363:         var start = Value(unit, "ExecStart");
364:         var executable = Regex.Match(start, @"^\{ path=(.*?) ; argv\[\]=", RegexOptions.CultureInvariant);
365:         if (!executable.Success)
366:             return false;
367: 
368:         var legacyPath = Path.Combine(install, LegacyAppHost);
369:         if (!string.Equals(Decode(executable.Groups[1].Value), legacyPath, StringComparison.Ordinal))
370:             return false;
371: 
372:         var candidates = new List<string> { RequiredUnitFile(Value(unit, "FragmentPath")) };
373:         candidates.AddRange(ParseWords(Value(unit, "DropInPaths")).Select(RequiredUnitFile));
374:         var replaced = false;
375:         foreach (var path in candidates.Distinct(StringComparer.Ordinal))
376:         {
377:             var text = File.ReadAllText(path);
378:             var updated = text.Replace(LegacyAppHost, AppHost, StringComparison.Ordinal);
379:             if (updated == text)
380:                 continue;
381: 
382:             File.WriteAllText(path, updated);
383:             replaced = true;
384:         }
385: 
386:         if (!replaced)
387:             throw new InvalidOperationException("Legacy ExecStart could not be retargeted to the deployed application host.");
388:         return true;
389:     }
