11: /// <remarks>
12: /// <list type="table">
13: /// <item><term>2026-11-04</term><description>TR-MCP-SERVICEUPDATE-001 criteria repeated-properties, preserve and
14: /// lifecycle (slice Z3): systemd 262 prints one <c>EnvironmentFiles=</c> line per environment file, and the redeploy of
15: /// 2026-11-04 stopped at the second line before any service change because the reader keyed lines by property name.
16: /// These rows state the reading the criterion needs: repeated lines of one property are one value, their non-empty
17: /// values in order separated by one space, so every environment file is validated and preserved.</description></item>
18: /// </list>
19: /// </remarks>
20: public sealed class ServiceUnitPropertiesContractTests
21: {
22:     /// <summary>
23:     /// The contract rows: systemctl show output and the properties a reader must return for it. Expected values come
24:     /// from the criterion and from systemd's output format, never from a reader under test.
25:     /// </summary>
26:     internal static readonly (string Name, string Output, (string Key, string Value)[] Expected)[] Rows =
27:     [
28:         ("single properties", "LoadState=loaded\nType=simple\n",
29:             [("LoadState", "loaded"), ("Type", "simple")]),
30:         ("two EnvironmentFiles lines", "EnvironmentFiles=/etc/a.env (ignore_errors=no)\nEnvironmentFiles=/etc/b.env (ignore_errors=yes)\n",
31:             [("EnvironmentFiles", "/etc/a.env (ignore_errors=no) /etc/b.env (ignore_errors=yes)")]),
32:         ("repeated lines keep their order", "DropInPaths=/etc/z.conf\nDropInPaths=/etc/a.conf\nDropInPaths=/etc/m.conf\n",
33:             [("DropInPaths", "/etc/z.conf /etc/a.conf /etc/m.conf")]),
34:         ("carriage returns are removed", "Type=simple\r\nEnvironmentFiles=/etc/a.env (ignore_errors=no)\r\nEnvironmentFiles=/etc/b.env (ignore_errors=no)\r\n",
35:             [("Type", "simple"), ("EnvironmentFiles", "/etc/a.env (ignore_errors=no) /etc/b.env (ignore_errors=no)")]),
36:         ("an empty value stays empty", "Environment=\nPrivateTmp=no\n",
37:             [("Environment", ""), ("PrivateTmp", "no")]),
38:         ("an empty repeated line adds nothing", "EnvironmentFiles=\nEnvironmentFiles=/etc/a.env (ignore_errors=no)\nEnvironmentFiles=\n",
39:             [("EnvironmentFiles", "/etc/a.env (ignore_errors=no)")]),
40:         ("a value keeps its own equals signs", "Environment=A=1 B=2\n",
41:             [("Environment", "A=1 B=2")]),
42:         ("a line without a property is ignored", "garbage\nType=exec\n\n",
43:             [("Type", "exec")]),
44:     ];
