100:     [Fact]
101:     public void ReferenceReader_MeetsEveryRow()
102:     {
103:         foreach (var row in Rows)
104:             Assert.True(Meets(ReferenceReader, row), row.Name);
105:     }
106: 
107:     /// <summary>Each wrong reader fails at least one contract row, so the rows discriminate (negative controls).</summary>
108:     /// <param name="index">The wrong reader's position in <see cref="WrongReaders"/>.</param>
109:     [Theory]
110:     [InlineData(0)]
111:     [InlineData(1)]
112:     [InlineData(2)]
113:     [InlineData(3)]
114:     [InlineData(4)]
115:     [InlineData(5)]
116:     public void WrongReader_FailsAtLeastOneRow(int index)
117:     {
118:         var (name, reader) = WrongReaders[index];
119:         Assert.Contains(Rows, row => !Meets(reader, row));
120:         Assert.False(string.IsNullOrEmpty(name));
121:     }
122: 
123:     /// <summary>The defect reader the redeploy met fails exactly the rows that repeat a property line.</summary>
124:     [Fact]
125:     public void DefectReader_FailsOnlyTheRepeatedRows()
126:     {
