3: /// <summary>
4: /// TEST-MCP-SERVICEUPDATE-001 for TR-MCP-SERVICEUPDATE-001 criterion startup-health-wait: the rows a Linux update's wait
5: /// for HTTP health after the start must meet, proven against an independent reference wait and against wrong waits
6: /// before the production wait changes (BDPv4 mock gate). The unit state, the health probe and the sleep are scripted,
7: /// so no row waits on real time. The same rows bind to the production wait in <see cref="ServiceUpdateTests"/>.
8: /// </summary>
9: /// <remarks>
10: /// <list type="table">
11: /// <item><term>2026-11-04</term><description>TR-MCP-SERVICEUPDATE-001 criteria startup-health-wait and lifecycle (slice Z3):
12: /// the redeploy of 2026-11-04 stopped a server that was starting normally, because the update probed health 10 times 2 s
13: /// apart while the server registers every workspace before it listens (93 s at 14:27). These rows state the wait the
14: /// criterion needs: probe while the unit stays active, up to the allowed probes; stop at once when the unit leaves the
15: /// active state; never stop a unit that answers within the allowed probes.</description></item>
16: /// </list>
17: /// </remarks>
18: public sealed class ServiceStartupHealthContractTests
19: {
20:     /// <summary>The outcomes a wait reports, by name.</summary>
21:     internal const string Healthy = "Healthy";
22: 
23:     /// <summary>The unit left the active state before it answered health.</summary>
24:     internal const string UnitStopped = "UnitStopped";
25: 
26:     /// <summary>The allowed probes were spent without a healthy answer.</summary>
27:     internal const string TimedOut = "TimedOut";
28: 
29:     /// <summary>
30:     /// One contract row: the unit states and probe answers the scripts return in order (the last one repeats), the
31:     /// allowed probes, and the outcome, probe count and sleep count the criterion requires.
32:     /// </summary>
33:     internal sealed record Row(string Name, string[] States, bool[] Answers, int MaxProbes, string Outcome, int Probes, int Sleeps);
34: 
35:     /// <summary>A wait as the contract sees it: it returns the outcome name and the probes it made.</summary>
36:     internal delegate (string Outcome, int Probes) StartupWait(Func<string> activeState, Func<bool> probe, Action<TimeSpan> sleep, int maxProbes, TimeSpan interval);
37: 
38:     /// <summary>The contract rows; expected values come from the criterion, never from a wait under test.</summary>
39:     internal static readonly Row[] Rows =
40:     [
41:         new("healthy at once", ["active"], [true], 120, Healthy, 1, 0),
42:         new("a server that answers on the 19th probe (95 s at 5 s)", ["active"], [false, false, false, false, false, false, false, false, false, false, false, false, false, false, false, false, false, false, true], 120, Healthy, 19, 18),
43:         new("the unit fails while starting", ["active", "active", "failed"], [false], 120, UnitStopped, 2, 2),
44:         new("the unit is inactive before the first probe", ["inactive"], [false], 120, UnitStopped, 0, 0),
45:         new("never healthy", ["active"], [false], 3, TimedOut, 3, 2),
46:         new("healthy on the last allowed probe", ["active"], [false, false, true], 3, Healthy, 3, 2),
47:     ];
48: 
49:     /// <summary>Independent reference wait: a bounded for loop that checks the unit before each probe.</summary>
50:     private static (string Outcome, int Probes) ReferenceWait(Func<string> activeState, Func<bool> probe, Action<TimeSpan> sleep, int maxProbes, TimeSpan interval)
51:     {
52:         for (var made = 0; made < maxProbes; made++)
53:         {
54:             if (!string.Equals(activeState(), "active", StringComparison.Ordinal)) return (UnitStopped, made);
55:             if (probe()) return (Healthy, made + 1);
56:             if (made + 1 < maxProbes) sleep(interval);
57:         }
58:         return (TimedOut, maxProbes);
59:     }
60: 
61:     /// <summary>Wrong waits each row set must reject; the first is the window the redeploy met.</summary>
62:     internal static readonly (string Name, StartupWait Wait)[] WrongWaits =
63:     [
64:         ("gives up after 10 probes", (state, probe, sleep, max, interval) => ReferenceWait(state, probe, sleep, Math.Min(max, 10), interval)),
65:         ("ignores the unit state", (_, probe, sleep, max, interval) => ReferenceWait(() => "active", probe, sleep, max, interval)),
66:         ("checks the unit only before the first probe", (state, probe, sleep, max, interval) =>
67:         {
68:             var first = state();
69:             return ReferenceWait(() => first, probe, sleep, max, interval);
70:         }),
71:         ("sleeps after the last probe too", (state, probe, sleep, max, interval) =>
72:         {
73:             var result = ReferenceWait(state, probe, sleep, max, interval);
74:             if (result.Item1 == TimedOut) sleep(interval);
75:             return result;
76:         }),
77:         ("probes before it checks the unit", (state, probe, sleep, max, interval) =>
78:         {
79:             var made = 0;
80:             while (made < max)
81:             {
82:                 var answer = probe();
