96:         var probeCalls = 0;
97:         var sleeps = 0;
98:         string State() => row.States[Math.Min(stateIndex++, row.States.Length - 1)];
99:         bool Probe() => row.Answers[Math.Min(probeCalls++, row.Answers.Length - 1)];
100:         var (outcome, probes) = wait(State, Probe, _ => sleeps++, row.MaxProbes, TimeSpan.FromSeconds(5));
