152:     /// (UseCaseFrLinks × UseCases), batched to avoid N+1.
153:     /// </summary>
154:     private static async Task<IReadOnlyDictionary<string, IReadOnlyList<LinkedUseCaseRef>>> LoadLinkedUseCasesByFrIdAsync(
155:         McpDbContext db,
156:         IReadOnlyCollection<string> frIds,
157:         CancellationToken ct)
158:     {
159:         if (frIds.Count == 0)
160:             return new Dictionary<string, IReadOnlyList<LinkedUseCaseRef>>(StringComparer.OrdinalIgnoreCase);
161: 
162:         var idSet = frIds.ToHashSet(StringComparer.OrdinalIgnoreCase);
163:         var rows = await db.UseCaseFrLinks
164:             .AsNoTracking()
165:             .Where(l => idSet.Contains(l.FrId))
166:             .Join(
167:                 db.UseCases.AsNoTracking(),
168:                 l => l.UseCaseId,
169:                 u => u.UseCaseId,
170:                 (l, u) => new { l.FrId, u.UseCaseId, u.Title, l.LinkType, l.LinkOrder })
171:             .OrderBy(x => x.FrId)
172:             .ThenBy(x => x.LinkOrder)
173:             .ThenBy(x => x.UseCaseId)
174:             .ToListAsync(ct)
175:             .ConfigureAwait(false);
176: 
177:         return rows
178:             .GroupBy(x => x.FrId, StringComparer.OrdinalIgnoreCase)
179:             .ToDictionary(
180:                 g => g.Key,
181:                 g => (IReadOnlyList<LinkedUseCaseRef>)g
182:                     .Select(x => new LinkedUseCaseRef(x.UseCaseId, x.Title, x.LinkType, x.LinkOrder))
183:                     .ToArray(),
184:                 StringComparer.OrdinalIgnoreCase);
185:     }
