155:         "ignores case in values" => (requested, baseline) => Collect(requested, (key, value) => !string.Equals(baseline(key), value, StringComparison.OrdinalIgnoreCase)),
156:         "empty map instead of null" => (requested, baseline) => ScriptedDelta(requested, baseline) ?? new Dictionary<string, string>(),
157:         _ => throw new ArgumentOutOfRangeException(nameof(wrong), wrong, "Unknown wrong delta builder."),
158:     };
159: 
160:     private static Dictionary<string, string>? Collect(IEnumerable<KeyValuePair<string, string?>> requested, Func<string, string, bool> keep)
161:     {
162:         var delta = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
163:         foreach (var (key, value) in requested)
164:         {
165:             if (value is not null && keep(key, value))
166:                 delta[key] = value;
167:         }
168: 
169:         return delta.Count > 0 ? delta : null;
170:     }
171: 
172:     private static bool SameDelta(Dictionary<string, string>? expected, Dictionary<string, string>? actual)
173:     {
174:         if (expected is null || actual is null)
175:             return expected is null && actual is null;
176: 
177:         return expected.Count == actual.Count
178:             && expected.All(pair => actual.TryGetValue(pair.Key, out var value) && string.Equals(value, pair.Value, StringComparison.Ordinal));
179:     }
180: }
