3: /// <summary>
4: /// FR-MCP-TRIAGESTORE-002 / TR-MCP-TRIAGESTORE-002: connect+command budget for triage intake,
5: /// session-log SaveChanges, and session-graph materialization. The shared
6: /// <see cref="Default"/> is 5 seconds. Session-log Submit and graph loads pass a longer budget.
7: /// Expiry fails as storage-unavailable instead of hanging until the REPL timeout.
8: /// </summary>
9: public static class StorageCommandBudget
10: {
11:     /// <summary>Triage intake and non-submit session-log save budget. Session-log Submit and graph loads do not use this value.</summary>
12:     public static readonly TimeSpan Default = TimeSpan.FromSeconds(5);
13: 
14:     /// <summary>Runs <paramref name="action"/> under <see cref="Default"/> and maps budget expiry to <see cref="StorageCommandBudgetExceededException"/>.</summary>
15:     /// <param name="action">The storage work.</param>
16:     /// <param name="cancellationToken">Caller cancellation.</param>
17:     /// <param name="budget">
18:     /// Optional per-call budget. <see langword="null"/> uses <see cref="Default"/> (5 seconds).
19:     /// Session-log Submit and graph materialization pass the configured budget here.
20:     /// </param>
21:     /// <returns>A task that completes when the work finishes or the budget expires.</returns>
22:     public static async Task ExecuteAsync(
23:         Func<CancellationToken, Task> action,
24:         CancellationToken cancellationToken,
25:         TimeSpan? budget = null)
26:     {
27:         ArgumentNullException.ThrowIfNull(action);
28:         var limit = budget ?? Default;
29:         if (limit <= TimeSpan.Zero)
30:             throw new ArgumentOutOfRangeException(nameof(budget), limit, "Storage command budget must be positive.");
31: 
32:         using var linked = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
33:         linked.CancelAfter(limit);
34:         try
35:         {
36:             await action(linked.Token).ConfigureAwait(false);
37:         }
38:         catch (OperationCanceledException) when (!cancellationToken.IsCancellationRequested)
39:         {
40:             throw new StorageCommandBudgetExceededException(limit);
41:         }
42:     }
43: 
44:     /// <summary>Runs <paramref name="action"/> and returns its result under the given storage budget.</summary>
45:     /// <typeparam name="T">Result type.</typeparam>
46:     /// <param name="action">The storage work.</param>
47:     /// <param name="cancellationToken">Caller cancellation.</param>
48:     /// <param name="budget">
49:     /// Optional per-call budget. <see langword="null"/> uses <see cref="Default"/> (5 seconds).
50:     /// </param>
51:     /// <returns>The action result.</returns>
52:     public static async Task<T> ExecuteAsync<T>(
53:         Func<CancellationToken, Task<T>> action,
54:         CancellationToken cancellationToken,
55:         TimeSpan? budget = null)
56:     {
57:         ArgumentNullException.ThrowIfNull(action);
58:         T result = default!;
59:         await ExecuteAsync(
60:             async ct => { result = await action(ct).ConfigureAwait(false); },
61:             cancellationToken,
62:             budget).ConfigureAwait(false);
63:         return result;
64:     }
65: }
