97:     private static async Task CaptureAsync(StreamReader reader, StringBuilder destination, CancellationToken cancellationToken)
98:     {
99:         var buffer = new char[4096];
100:         while (true)
101:         {
102:             var read = await reader.ReadAsync(buffer.AsMemory(0, buffer.Length), cancellationToken).ConfigureAwait(false);
103:             if (read == 0)
104:                 return;
105: 
106:             lock (destination)
107:                 destination.Append(buffer, 0, read);
108:         }
109:     }
