111:     private static async Task WaitForOutputAsync(
112:         StringBuilder output,
113:         Func<string, bool> predicate,
114:         TimeSpan timeout,
115:         CancellationToken cancellationToken)
116:     {
117:         var deadline = DateTimeOffset.UtcNow.Add(timeout);
118:         while (DateTimeOffset.UtcNow < deadline)
119:         {
120:             cancellationToken.ThrowIfCancellationRequested();
121:             string snapshot;
122:             lock (output)
123:                 snapshot = output.ToString();
124: 
125:             if (predicate(snapshot))
126:                 return;
127: 
128:             await Task.Delay(TimeSpan.FromMilliseconds(100), cancellationToken).ConfigureAwait(false);
129:         }
130: 
131:         string finalSnapshot;
132:         lock (output)
133:             finalSnapshot = output.ToString();
134:         throw new TimeoutException($"Timed out waiting for stdio output. Current stdout: {finalSnapshot}");
135:     }
